import axios from "axios";
import { createContext, useContext, useEffect, useState } from "react";
import { useLocation, useSearchParams } from "react-router-dom";
import {
  KEYS,
  migrateLegacyCustomerId,
  persistCustomerId,
} from "../../utils/wixStorage";
import { isStorefrontPath } from "./storefrontRoutes";

const AppStatusContext = createContext({
  loading: true,
  appEnabled: true,
  isStorefront: false,
});

export const AppStatusProvider = ({ children }) => {
  const location = useLocation();
  const [searchParams] = useSearchParams();
  const storefront = isStorefrontPath(location.pathname);

  const [loading, setLoading] = useState(storefront);
  const [appEnabled, setAppEnabled] = useState(!storefront);

  const shop_id =
    searchParams.get("shopid") ||
    searchParams.get("shopId") ||
    localStorage.getItem(KEYS.SHOP_ID);
  const user_id = searchParams.get("customerId");
  const instance =
    searchParams.get("instance") ||
    localStorage.getItem(KEYS.INSTANCE);

  useEffect(() => {
    if (shop_id) {
      localStorage.setItem(KEYS.SHOP_ID, shop_id);
    }
    if (user_id) {
      persistCustomerId(user_id);
    }
    migrateLegacyCustomerId();
  }, [shop_id, user_id]);

  useEffect(() => {
    if (!storefront) {
      setAppEnabled(true);
      setLoading(false);
      return;
    }

    let cancelled = false;

    const checkAppStatus = async () => {
      try {
        // Check if we have a recent validation cached
        const lastValidationTime = localStorage.getItem("app_status_validated_at");
        const now = Date.now();
        const CACHE_DURATION = 60 * 60 * 1000; // 1 hour in milliseconds

        // Skip validation if cached and still valid
        if (lastValidationTime && (now - parseInt(lastValidationTime)) < CACHE_DURATION) {
          const cachedEnabled = localStorage.getItem("app_status_enabled");
          if (cachedEnabled !== null) {
            setAppEnabled(cachedEnabled === "true");
            setLoading(false);
            return;
          }
        }

        const adminIdLocal =
          shop_id || localStorage.getItem(KEYS.SHOP_ID) || undefined;

        const response = await axios.get(
          `${process.env.REACT_APP_BACKEND_HOST}/api/users/app-status-verify-app-status`,
          {
            params: {
              instance: instance || undefined,
              adminIdLocal: adminIdLocal || undefined,
            },
          },
        );

        if (cancelled) return;

        if (response.data?.success) {
          const isEnabled = Boolean(response.data.data);
          setAppEnabled(isEnabled);
          // Cache the result
          localStorage.setItem("app_status_enabled", String(isEnabled));
          localStorage.setItem("app_status_validated_at", String(now));

          if (response.data.adminId) {
            localStorage.setItem(KEYS.SHOP_ID, String(response.data.adminId));
          }
        } else {
          setAppEnabled(false);
          localStorage.setItem("app_status_enabled", "false");
          localStorage.setItem("app_status_validated_at", String(now));
        }
      } catch (err) {
        console.error("App status check failed:", err?.message || err);
        if (!cancelled) setAppEnabled(false);
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    // DO NOT BLOCK storefront rendering on app status check
    // Set loading to false immediately for storefront to render
    setLoading(false);

    // Perform status check asynchronously in background
    // This allows storefront to show immediately while status validates
    setTimeout(checkAppStatus, 100);

    return () => {
      cancelled = true;
    };
  }, [storefront, instance, shop_id]);

  return (
    <AppStatusContext.Provider
      value={{ loading, appEnabled, isStorefront: storefront }}
    >
      {children}
    </AppStatusContext.Provider>
  );
};

export const useAppStatus = () => useContext(AppStatusContext);
